import { test, expect } from '@playwright/test';

test.describe('Table Loading State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display loading state while fetching data', async ({ page }) => {
    // Trigger data fetching
    await page.getByRole('button', { name: 'Fetch Data' }).click();

    // Expect loading indicator to be visible
    const loadingIndicator = page.getByText('Loading...');
    await expect(loadingIndicator).toBeVisible();

    // Wait for data to load
    await page.waitForResponse(response => response.url().includes('/api/data') && response.status() === 200);

    // Expect loading indicator to be hidden after data is fetched
    await expect(loadingIndicator).toBeHidden();
  });

  test('should display data in the table after loading', async ({ page }) => {
    // Trigger data fetching
    await page.getByRole('button', { name: 'Fetch Data' }).click();

    // Wait for data to load
    await page.waitForResponse(response => response.url().includes('/api/data') && response.status() === 200);

    // Expect table to show data
    const tableRow = page.getByRole('row', { name: 'Sample Data Row' });
    await expect(tableRow).toBeVisible();
  });
});
